import {resonanceRule} from './resonance.js';
import {fusedPair,companionRole,fusionKey} from './pet-fusion.js';
import {THIRD_JOBS} from './third-jobs.js';
const effects={
 'attack-magic':{magic:.12,bonus:.1},'attack-defense':{petArmor:.10,armor:.05},'attack-support':{leech:.04,bounty:.15},
 'magic-defense':{petArmor:.08,magic:.08},'magic-support':{refund:2,autoPower:.06},'defense-support':{leech:.05,refund:1}
};
export function companionResonance(player,pet){const rule=resonanceRule(player.job,companionRole(pet));if(!rule||!player.thirdJob||!fusedPair(pet))return rule;const pair=fusedPair(pet),key=fusionKey(pet.fusion.main,pet.fusion.sub),extra=effects[key];const role=companionRole(pet),adjust=player.job==='monk'&&role==='magic'?{rebirthBonus:.4}:player.job==='hunter'&&role==='magic'?{rebirthSpread:.85}:player.job==='performer'&&role==='magic'?{rebirthSpread:.7}:player.job==='performer'&&role==='attack'?{rebirthBonus:.15}:player.job==='performer'&&role==='defense'?{rebirthArmor:.35}:player.job==='priest'&&role==='magic'?{spread:.8}:player.job==='priest'&&role==='defense'?{rebirthPetArmor:.85}:{};return {...rule,name:`${THIRD_JOBS[player.job].name}・${pair.name}`,description:`${rule.description}；融合特性：${pair.style}。${Object.keys(adjust).length?`三轉校準：${Object.entries(adjust).map(([k,v])=>`${({rebirthSpread:'擴散每體倍率',spread:'擴散每體倍率',rebirthBonus:'主攻追加倍率',rebirthArmor:'主攻追加自身DEF',rebirthPetArmor:'主攻追加寵物DEF'})[k]}${Math.round(v*100)}%`).join('、')}。`:''}${Object.entries(extra).map(([k,v])=>({magic:`追加寵物MATK${v*100}%`,bonus:`技能倍率+${v*100}%`,petArmor:`追加寵物DEF${v*100}%`,armor:`追加自身DEF${v*100}%`,leech:`傷害轉治療${v*100}%`,bounty:`掠獵金幣收益`,refund:`每次退還${v}SP`,autoPower:`自詠倍率+${v*100}%`})[k]).join('、')}`,transform:{...rule.transform,...adjust,...Object.fromEntries(Object.entries(extra).map(([k,v])=>[k,(rule.transform?.[k]||0)+v]))}};}
